@RequestMapping(method = {RequestMethod.GET, RequestMethod.POST, RequestMethod.OPTIONS}, value = "{channelId}/{apiName}/**")
    public ResponseEntity<Object> gateway(HttpServletRequest httpServletRequest, HttpServletResponse httpServletResponse,
                                          @PathVariable Long channelId, @PathVariable String apiName) {
        String urlSurfix = resolveUrlSurfix(httpServletRequest);
        Pipeline pipeline = createPipeline(httpServletRequest, httpServletResponse, channelId, apiName);
        pipeline.pipelineContext().addParameter(PipeLineConstants.HTTP_URL_SURFIX_MAP_KEY, urlSurfix);
        pipeline.invokeNext();
        return response(pipeline);
    }

@Override
    public void invokeNext() {
        PipelineHandler handler = handlerChain.getAndRemoveHead();
        if (handler == null) {
            // todo
            return;
        }
        try {
            handler.handle(this);
        } catch (GatewayException e) {
            log.error("服务出异常："+e.toString(), e);
            if (abstractErrorHandler != null) {
                abstractErrorHandler.onError(this.context, e);
            }
        }
    }

@Override
    public void handle(Pipeline pipeline) {
        if (precondition(pipeline)) {
            doHandle(pipeline);
        }
        pipeline.invokeNext();
    }

@Override
    protected void doHandle(Pipeline pipeline) {
        UserDTO userInfo = pipeline.pipelineContext().pipelineRequest().getUserInfo();
        if (userInfo != null && StringUtils.isNotBlank(userInfo.getAccountId())) {
            try {
                // 查询店铺信息
                List<AuthBranchE> authBranchList = authBranchRepository.selectByAccountId(Long.parseLong(userInfo.getAccountId()));
                if (CollectionUtils.isNotEmpty(authBranchList)) {
                    List<MerchantBranchInfoDTO> branchInfoDTOList = authBranchList.stream().map(this::convertMerchantBranchInfoDTO).collect(Collectors.toList());
                    Map<String, String> headers = pipeline.pipelineContext().getParameter(PipeLineConstants.HTTP_HEADER_MAP_KEY);
                    if (headers == null) {
                        headers = new HashMap<>();
                        pipeline.pipelineContext().addParameter(PipeLineConstants.HTTP_HEADER_MAP_KEY, headers);
                    }
                    // 店铺列表
                    headers.put(PipeLineConstants.HEADER_KEY_BRANCHES, JSON.toJSONString(branchInfoDTOList));
                }
            } catch (Exception e) {
                log.warn("ParamBranchHandler warn:{}", e);
            }
        }
    }

@Cacheable(value = CacheConstants.CACHE_NAME_AUTH_BRANCH, key = "#accountId+''")
    public List<AuthBranchE> selectByAccountId(Long accountId) {
        List<AuthBranchDO> authBranchList = authBranchDOMapper.selectByAccountId(accountId);
        if (CollectionUtils.isEmpty(authBranchList)) {
            return null;
        }
        return authBranchList.stream().map(authBranchConverter::toAuthBranchE).collect(Collectors.toList());
    }

private Pipeline createPipeline(HttpServletRequest httpServletRequest, HttpServletResponse httpServletResponse, Long channelId, String apiName) {
        PipelineRequest request = new PipelineRequest();
        request.setHttpServletRequest(httpServletRequest);
        request.setHttpServletResponse(httpServletResponse);
        request.setChannelId(channelId);
        request.setApiName(apiName);
        if (SecurityUtil.obtainUser() != null) {
            request.setUserInfo(SecurityUtil.obtainUser());
        }

        PipelineHandlerChain chain = new DefaultPipelineHandlerChain();
        chain.addTail(authHandler);
        chain.addTail(authorizationHandler);
        chain.addTail(writeBlackListHandler);
        chain.addTail(paramExtractHandler);
        chain.addTail(paramBranchHandler);
        chain.addTail(userPopulateHandler);
        chain.addTail(rateLimitHandler);
        chain.addTail(dispatchRequestHandler);
        chain.addTail(afterResponseHandler);
        return new DefaultPipeline(request, new PipelineResponse(), abstractErrorHandler, chain);
    }

